const money=(v,d=0)=>Number.isFinite(v)?v.toLocaleString('zh-TW',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
export function aggregateHistory(records){
 const sessions=records.filter(r=>!r.deleted).slice().sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt))||String(a.id).localeCompare(String(b.id)));
 let net=0,closedNet=0,count=0,wins=0,losses=0,profit=0,loss=0,streak=0,maxStreak=0,mdd=0,peak=0,mddSum=0,mddCount=0,incompleteEquity=0;const equity=[0],series=[];
 const add=value=>{equity.push(value);peak=Math.max(peak,value);mdd=Math.max(mdd,peak-value)};
 for(const r of sessions){
  const capital=r.cfg?.capital,points=Array.isArray(r.equity)?r.equity:[];let valid=0;
  if(Number.isFinite(capital))for(const point of points)if(Number.isFinite(point.value)){add(net+point.value-capital);valid++}
  if(!valid)incompleteEquity++;
  const value=Number.isFinite(r.net)?r.net:0;net+=value;add(net);
  for(const t of r.trades??[]){if(!Number.isFinite(t.net))continue;count++;closedNet+=t.net;if(t.net>0){wins++;profit+=t.net;streak=0}else if(t.net<0){losses++;loss-=t.net;streak++;maxStreak=Math.max(maxStreak,streak)}else streak=0}
  if(Number.isFinite(r.stats?.mdd)){mddSum+=r.stats.mdd;mddCount++}
  series.push({n:series.length+1,date:r.date,net:value,cumulative:net,average:net/(series.length+1)});
 }
 const avgWin=wins?profit/wins:null,avgLoss=losses?loss/losses:null;
 return {sessions:sessions.length,net,count,closedNet,winRate:count?wins/count:null,avgSessionNet:sessions.length?net/sessions.length:null,expectancy:count?closedNet/count:null,avgWin,avgLoss,payoff:wins&&losses?avgWin/avgLoss:null,pf:losses?profit/loss:wins?Infinity:null,mdd,maxStreak,avgSessionMdd:mddCount?mddSum/mddCount:null,incompleteEquity,equity,series};
}
// Preserve first/last and local extrema for drawing; metrics use every original point.
function sample(points,limit=1000){if(points.length<=limit)return points.map((v,i)=>({v,i}));const step=Math.ceil((points.length-2)/((limit-2)/2)),out=[{v:points[0],i:0}];for(let start=1;start<points.length-1;start+=step){let lo=start,hi=start;for(let i=start;i<Math.min(points.length-1,start+step);i++){if(points[i]<points[lo])lo=i;if(points[i]>points[hi])hi=i}for(const i of [...new Set([lo,hi])].sort((a,b)=>a-b))out.push({v:points[i],i})}out.push({v:points.at(-1),i:points.length-1});return out}
function frame(title,body,low,high){return `<svg viewBox="0 0 760 250" role="img" aria-label="${title}"><title>${title}</title><g fill="none" stroke="#2a3b44">${[20,75,130,185,220].map(y=>`<path d="M65 ${y}H745"/>`).join('')}</g><g fill="#8fa4af" font-family="Arial,sans-serif" font-size="11"><text x="4" y="25">${money(high)}</text><text x="4" y="224">${money(low)}</text></g>${body}</svg>`}
function cumulativeChart(s){const points=s.equity,low=Math.min(0,...sample(points).map(x=>x.v)),high=Math.max(0,...sample(points).map(x=>x.v)),span=high-low||1,y=v=>220-(v-low)/span*200,x=i=>65+i/Math.max(1,points.length-1)*680;const path=sample(points).map((p,i)=>(i?'L':'M')+x(p.i).toFixed(2)+' '+y(p.v).toFixed(2)).join(' ');return frame('累積損益曲線（包含保存時的浮動損益）',`<path d="M65 ${y(0)}H745" stroke="#66715b" stroke-dasharray="4 4"/><path d="${path}" fill="none" stroke="#d9bd79" stroke-width="2"/><text x="65" y="244" fill="#8fa4af" font-size="11">保存順序起點</text><text x="635" y="244" fill="#8fa4af" font-size="11">最新保存紀錄</text>`,low,high)}
function averageChart(s){const data=s.series.slice(-80),low=Math.min(0,...data.flatMap(x=>[x.net,x.average])),high=Math.max(0,...data.flatMap(x=>[x.net,x.average])),span=high-low||1,y=v=>220-(v-low)/span*200,w=680/Math.max(1,data.length),x=i=>65+(i+.5)*w;const bars=data.map((p,i)=>`<rect x="${x(i)-w*.3}" y="${Math.min(y(0),y(p.net))}" width="${Math.max(1,w*.6)}" height="${Math.max(1,Math.abs(y(p.net)-y(0)))}" fill="${p.net>=0?'#df837b':'#5fc2aa'}" opacity=".7"><title>第${p.n}次 ${p.date}：損益${money(p.net)}元；累積每次平均${money(p.average,1)}元</title></rect>`).join('');const line=data.map((p,i)=>(i?'L':'M')+x(i).toFixed(2)+' '+y(p.average).toFixed(2)).join(' ');return frame('每次練習損益與累積平均',`<path d="M65 ${y(0)}H745" stroke="#66715b"/>${bars}<path d="${line}" fill="none" stroke="#d9bd79" stroke-width="2"/>${data.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.average)}" r="2" fill="#d9bd79"/>`).join('')}<text x="65" y="244" fill="#8fa4af" font-size="11">第${data[0]?.n??0}次</text><text x="665" y="244" fill="#8fa4af" font-size="11">第${data.at(-1)?.n??0}次</text>`,low,high)}
export function historySummaryHTML(s){if(!s.sessions)return '<details class="statDisclosure"><summary>全部操作的累積與平均績效</summary><div class="disclosureBody empty">儲存練習後，這裡會顯示全部操作的平均績效與圖表。</div></details>';
 const cards=[['累積損益',money(s.net)+' 元','所有未刪除保存紀錄的成本後損益，包含快照中的浮動損益。'],['平均每次練習損益',money(s.avgSessionNet,1)+' 元','累積損益 ÷ 保存練習次數。'],['平均每筆交易損益／期望值',money(s.expectancy,1)+' 元','已平倉交易淨損益總和 ÷ 交易筆數，不含浮動損益。'],['整體勝率',s.winRate==null?'—':money(s.winRate*100,1)+'%','全部已平倉交易合併計算，不直接平均各次勝率。'],['平均獲利',s.avgWin==null?'—':money(s.avgWin,1)+' 元','所有獲利交易的淨利總和 ÷ 獲利筆數。'],['平均虧損',s.avgLoss==null?'—':money(s.avgLoss,1)+' 元','所有虧損交易的淨損絕對值總和 ÷ 虧損筆數。'],['平均盈虧比',money(s.payoff,2),'平均獲利 ÷ 平均虧損；兩類都有時才計算。'],['獲利因子（Profit Factor）',s.pf===Infinity?'∞（尚無虧損）':money(s.pf,2),'全部獲利總和 ÷ 全部虧損絕對值，不平均單次比值。'],['合併最大回撤（MDD）',money(s.mdd)+' 元','依保存順序銜接各練習的損益路徑，計算最大高低回落。'],['平均每次最大回撤',money(s.avgSessionMdd,1)+' 元','各保存紀錄的最大回撤取平均，與合併回撤不同。'],['最大連續虧損次數',money(s.maxStreak)+' 次','按保存順序合併已平倉交易，連續虧損的最長次數。'],['練習／交易筆數',`${s.sessions} 次／${s.count} 筆`,'交易按FIFO平倉配對；分批進出可能產生多筆。']];
 return `<details class="statDisclosure"><summary>全部操作的累積與平均績效</summary><div class="disclosureBody"><p class="historyScope">依本瀏覽器全部未刪除的保存紀錄計算，不受下方搜尋影響；未儲存的操作不計入。舊版重複快照及匯入副本仍個別計入。</p><div class="statsgrid explainedStats">${cards.map(([a,b,c])=>`<div><span>${a}</span><strong>${b}</strong><p>${c}</p></div>`).join('')}</div><div class="historyCharts"><section><h3>累積損益曲線</h3>${cumulativeChart(s)}<p>包含各次練習內已保存的浮動損益。圖表取樣繪製，指標使用完整紀錄。</p></section><section><h3>每次損益與累積平均</h3>${averageChart(s)}<p>柱狀＝每次損益；金線＝從第一筆起的平均每次損益。${s.sessions>80?'柱狀圖顯示最近80次。':''}</p></section></div><p class="historyScope">各次練習視為獨立操作，並非連續資金帳戶；本金、加減資與期間尚未一致，年複合報酬率（CAGR）暫不計算。${s.incompleteEquity?'有'+s.incompleteEquity+'筆紀錄缺少權益序列，只以保存損益銜接，合併回撤可能低估。':''}</p></div></details>`;
}
